{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Plans — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f7fbf9;--card:#ffffff;--muted:#617073;--accent:#2b7a66;--accent-2:#4aa68a;--glass:rgba(255,255,255,0.6)}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial;color:#0f261f;background:var(--bg);-webkit-font-smoothing:antialiased}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:linear-gradient(180deg,rgba(255,255,255,0.6),rgba(255,255,255,0.3));backdrop-filter:blur(6px);position:sticky;top:0;z-index:30;border-bottom:1px solid rgba(15,38,31,0.04)}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:44px;height:44px;background:var(--accent);border-radius:8px;display:grid;place-items:center;color:white;font-weight:700}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none;font-weight:600;font-size:14px}
    .cta{background:var(--accent);color:#fff;padding:8px 14px;border-radius:8px;text-decoration:none;font-weight:700}
    main{max-width:1100px;margin:34px auto;padding:0 22px}
    .hero{display:grid;grid-template-columns:1fr;gap:18px;padding:22px;border-radius:14px;background:linear-gradient(180deg,var(--card),#f8fffc);box-shadow:0 6px 24px rgba(11,34,29,0.06);border:1px solid rgba(11,34,29,0.04);overflow:hidden;position:relative}
    .hero .lead{font-size:20px;color:var(--muted);line-height:1.45}
    .hero h1{margin:0;font-size:28px;color:#073326}
    .cols{display:grid;grid-template-columns:1fr 320px;gap:20px;align-items:start}
    .card{background:var(--card);padding:18px;border-radius:12px;border:1px solid rgba(11,34,29,0.04)}
    .tiers{display:flex;flex-direction:column;gap:12px}
    .tier{padding:16px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.9),var(--glass));border:1px solid rgba(11,34,29,0.04)}
    .tier h3{margin:0 0 6px 0;font-size:18px}
    .price{font-weight:800;color:var(--accent);font-size:20px}
    .muted{color:var(--muted);font-size:14px}
    .actions{display:flex;gap:10px;margin-top:10px}
    .btn{padding:8px 12px;border-radius:8px;border:0;cursor:pointer}
    .btn-primary{background:var(--accent);color:#fff}
    .btn-ghost{background:transparent;border:1px solid rgba(11,34,29,0.06)}
    .features{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-top:8px}
    .feature{font-size:14px;color:var(--muted)}
    footer{max-width:1100px;margin:28px auto;padding:20px;text-align:center;color:var(--muted)}
    .pattern{position:absolute;right:-40px;top:-40px;width:320px;height:320px;opacity:0.12;background-image:url('assets/img/pattern.svg');background-size:cover;transform:rotate(10deg)}
    .reveal{opacity:0;transform:translateY(14px);transition:opacity 520ms cubic-bezier(.2,.9,.3,1),transform 520ms cubic-bezier(.2,.9,.3,1)}
    .reveal.is-visible{opacity:1;transform:none}
    /* Responsive */
    @media (max-width:900px){.cols{grid-template-columns:1fr}.pattern{display:none}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">HM</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav aria-label="Main navigation">
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="conditions.html">Conditions</a>
      <a href="approach.html">Method</a>
      <a href="pricing.html" style="color:var(--accent)">Plans</a>
      <a href="about.html">Team</a>
      <a href="book.html">Schedule</a>
      <a href="contact.html">Reach</a>
    </nav>
    <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
  </header>

  <main>
    <section class="hero reveal" aria-labelledby="plans-heading">
      <div class="pattern" aria-hidden="true"></div>
      <div>
        <h1 id="plans-heading">Memberships built around steady support</h1>
        <p class="lead">Structured monthly guidance for people who want practical integrative habits without added complexity. Choose a steady level of support — adapt when life asks for it.</p>
        <div style="margin-top:14px;display:flex;gap:10px;flex-wrap:wrap">
          <button class="btn btn-primary" id="openExercise">Try a short exercise</button>
          <a class="btn btn-ghost" href="#plans">Compare plans</a>
        </div>
      </div>
    </section>

    <section class="cols" style="margin-top:20px">
      <div>
        <div class="card reveal">
          <h2 style="margin-top:0">How membership works</h2>
          <p class="muted">A monthly subscription is a steady container: one guided planning session each month, access to short skill modules, and a flexible number of check-ins depending on the tier. Use the membership for rhythm, not one-off fixes.</p>
          <div style="margin-top:12px;display:flex;gap:8px;flex-wrap:wrap">
            <div style="padding:8px 10px;border-radius:8px;background:#f1fbf8;border:1px solid rgba(74,166,138,0.08);font-weight:700;color:var(--accent-2)">Monthly planning session</div>
            <div style="padding:8px 10px;border-radius:8px;background:#fff;border:1px solid rgba(11,34,29,0.04);color:var(--muted)">Guided mini-modules</div>
            <div style="padding:8px 10px;border-radius:8px;background:#fff;border:1px solid rgba(11,34,29,0.04);color:var(--muted)">Member portal & resources</div>
          </div>
        </div>

        <div class="card" style="margin-top:12px">
          <h3 style="margin:0 0 8px 0">Compare tiers</h3>
          <div class="tiers" id="plans">
            <div class="tier reveal">
              <h3>Harbor — Foundation</h3>
              <div class="muted">Simple monthly rhythm for maintenance</div>
              <div style="margin-top:10px" class="price">$49 / month</div>
              <div class="features">
                <div class="feature">1 monthly planning session (30m)</div>
                <div class="feature">Access to core modules</div>
                <div class="feature">Email check-ins (asynchronous)</div>
                <div class="feature">Member resource library</div>
              </div>
              <div class="actions"><button class="btn btn-primary">Choose Harbor</button><button class="btn btn-ghost">Learn more</button></div>
            </div>

            <div class="tier reveal">
              <h3>Compass — Guided</h3>
              <div class="muted">Deeper planning and regular touchpoints</div>
              <div style="margin-top:10px" class="price">$129 / month</div>
              <div class="features">
                <div class="feature">Monthly planning (50m)</div>
                <div class="feature">Two brief check-ins per month</div>
                <div class="feature">Priority scheduling</div>
                <div class="feature">Course cycle access</div>
              </div>
              <div class="actions"><button class="btn btn-primary">Choose Compass</button><button class="btn btn-ghost">Learn more</button></div>
            </div>

            <div class="tier reveal">
              <h3>Lantern — Support</h3>
              <div class="muted">Frequent touch and personalised coaching</div>
              <div style="margin-top:10px" class="price">$249 / month</div>
              <div class="features">
                <div class="feature">Monthly planning (80m) + weekly check-ins</div>
                <div class="feature">Direct messaging</div>
                <div class="feature">Custom module path</div>
                <div class="feature">Priority booking + extended resources</div>
              </div>
              <div class="actions"><button class="btn btn-primary">Choose Lantern</button><button class="btn btn-ghost">Contact us</button></div>
            </div>

          </div>
        </div>
      </div>

      <aside class="card reveal">
        <h3 style="margin-top:0">Why membership?</h3>
        <p class="muted">Membership supports learning and habit formation. We emphasize clear, teachable practices and realistic pacing so you can try things and adjust without pressure.</p>
        <div style="margin-top:12px">
          <strong>What's included</strong>
          <ul style="margin:8px 0 0 18px;color:var(--muted)">
            <li>Structured monthly planning</li>
            <li>Short guided modules (breathing, sleep habits, stress mapping)</li>
            <li>Access to community resources</li>
          </ul>
        </div>
        <div style="margin-top:16px"><a class="btn btn-primary" href="book.html">Start with a planning session</a></div>
      </aside>
    </section>

    <section style="margin-top:20px" class="reveal">
      <div class="card">
        <h3 style="margin-top:0">A note on clinical boundaries</h3>
        <p class="muted">Our memberships provide education, coaching, and integrative planning. They are not a substitute for urgent or emergency medical care. For acute issues, contact your local provider or emergency services.</p>
      </div>
    </section>

    <section style="margin-top:20px" class="reveal">
      <div class="card">
        <h3 style="margin-top:0">Stories from members</h3>
        <blockquote style="margin:8px 0;color:var(--muted)">"The monthly rhythm made a real difference — small experiments that fit my week." — A member in {{CITY}}</blockquote>
      </div>
    </section>

    <section style="margin-top:20px" class="reveal card">
      <h3 style="margin-top:0">Ready to test a short practice?</h3>
      <p class="muted">Try a guided breathing or journaling exercise right now. It takes under five minutes and you can close at any time.</p>
      <div style="margin-top:12px"><button class="btn btn-primary" id="openExercise2">Try it now</button></div>
    </section>

  </main>

  <footer>
    <div>Questions? Call {{PHONE}} or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    <div style="margin-top:6px;color:var(--muted)">© <span id="year"></span> {{BUSINESS_NAME}}</div>
  </footer>

  <!-- Guided exercise modal -->
  <div id="exerciseModal" role="dialog" aria-modal="true" aria-hidden="true" style="position:fixed;inset:0;display:none;align-items:center;justify-content:center;padding:24px;z-index:60">
    <div style="background:rgba(7,51,38,0.9);color:white;padding:18px;border-radius:12px;max-width:720px;width:100%;box-shadow:0 12px 48px rgba(2,10,8,0.5)">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <h2 style="margin:0;font-size:18px">Short guided practice</h2>
        <button id="closeExercise" style="background:transparent;border:0;color:white;font-size:18px;cursor:pointer">✕</button>
      </div>
      <div style="margin-top:12px;display:grid;grid-template-columns:1fr 220px;gap:12px">
        <div>
          <label style="display:block;margin-bottom:6px">Choose a short practice</label>
          <select id="exerciseMode" style="width:100%;padding:8px;border-radius:8px;border:0">
            <option value="breath">Breathing (2 minutes)</option>
            <option value="journaling">Journaling (3 minutes)</option>
            <option value="intention">Intention setting (90s)</option>
          </select>
          <div id="exerciseBody" style="margin-top:12px;color:#e6f6ee;font-size:15px;min-height:120px">
            <p style="margin:0">Gentle, brief guidance appears here when you start. The practice is educational and optional; stop any time.</p>
          </div>
          <div style="margin-top:12px;display:flex;gap:8px">
            <button class="btn btn-primary" id="startExercise">Start</button>
            <button class="btn btn-ghost" id="stopExercise">Stop</button>
          </div>
        </div>
        <div style="display:grid;place-items:center">
          <svg id="breathCircle" width="160" height="160" viewBox="0 0 100 100" aria-hidden="true">
            <defs>
              <linearGradient id="g1" x1="0" x2="1">
                <stop offset="0" stop-color="#4aa68a"/>
                <stop offset="1" stop-color="#2b7a66"/>
              </linearGradient>
            </defs>
            <circle cx="50" cy="50" r="28" fill="url(#g1)" opacity="0.12" />
            <circle id="animCircle" cx="50" cy="50" r="28" fill="#fff" opacity="0.06" stroke="#fff" stroke-opacity="0.06" />
          </svg>
          <div style="margin-top:10px;color:#cfeee0;font-weight:700" id="timerLabel">Ready</div>
        </div>
      </div>
    </div>
  </div>

  <script>
    // Accessibility: prefer-reduced-motion check
    const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    document.querySelectorAll('.reveal').forEach(el => {
      if (reduceMotion) el.classList.add('is-visible');
    });
    if (!reduceMotion && 'IntersectionObserver' in window) {
      const obs = new IntersectionObserver((entries) => {
        entries.forEach(e => { if (e.isIntersecting) e.target.classList.add('is-visible'); });
      }, {threshold:0.12});
      document.querySelectorAll('.reveal').forEach(el => obs.observe(el));
    }

    // Modal + guided practice
    const modal = document.getElementById('exerciseModal');
    const openButtons = [document.getElementById('openExercise'), document.getElementById('openExercise2')];
    openButtons.forEach(b => { if (b) b.addEventListener('click', openModal); });
    document.getElementById('closeExercise').addEventListener('click', closeModal);
    document.getElementById('startExercise').addEventListener('click', startExercise);
    document.getElementById('stopExercise').addEventListener('click', stopExercise);

    function openModal(){ modal.style.display='flex'; modal.setAttribute('aria-hidden','false'); document.getElementById('exerciseMode').focus(); }
    function closeModal(){ stopExercise(); modal.style.display='none'; modal.setAttribute('aria-hidden','true'); }

    let timer = null; let remaining = 0; let stepIndex = 0;
    const timerLabel = document.getElementById('timerLabel');
    const animCircle = document.getElementById('animCircle');
    const bodyBox = document.getElementById('exerciseBody');

    function setTimerDisplay(text){ timerLabel.textContent = text; }

    function startExercise(){ stopExercise(); const mode = document.getElementById('exerciseMode').value;
      if (mode === 'breath') startBreathing();
      if (mode === 'journaling') startJournaling();
      if (mode === 'intention') startIntention();
    }
    function stopExercise(){ if (timer) {clearInterval(timer); timer=null;} setTimerDisplay('Stopped'); animCircle.setAttribute('r',28); }

    function startBreathing(){ const cycles = 6; const inhale = 4000; const hold = 800; const exhale = 4000; let cycle=0; bodyBox.innerHTML = '<p style="margin:0">Follow the circle: inhale as it grows, exhale as it shrinks. Pause at the gentle hold if that suits you.</p>';
      setTimerDisplay('Get ready'); let phase='inhale'; animateBreath();
      function animateBreath(){ if (cycle>=cycles){ setTimerDisplay('Complete'); return; } if (phase==='inhale'){ remaining = inhale/1000; setTimerDisplay('Inhale'); expandCircle(); timer = setInterval(()=>{ remaining--; if (remaining<=0){ clearInterval(timer); phase='hold'; animateBreath(); } },1000); }
        else if (phase==='hold'){ remaining = hold/1000; setTimerDisplay('Hold'); timer = setInterval(()=>{ remaining--; if (remaining<=0){ clearInterval(timer); phase='exhale'; animateBreath(); } },1000); }
        else if (phase==='exhale'){ remaining = exhale/1000; setTimerDisplay('Exhale'); shrinkCircle(); timer = setInterval(()=>{ remaining--; if (remaining<=0){ clearInterval(timer); phase='inhale'; cycle++; animateBreath(); } },1000); }
      }
      function expandCircle(){ if (reduceMotion){ animCircle.setAttribute('r',32); } else {
        animCircle.animate([{r:28},{r:40}],{duration:inhale,fill:'forwards'}).onfinish=()=>{}; }
      }
      function shrinkCircle(){ if (reduceMotion){ animCircle.setAttribute('r',24); } else {
        animCircle.animate([{r:40},{r:28}],{duration:exhale,fill:'forwards'}).onfinish=()=>{}; }
      }
    }

    function startJournaling(){ const duration = 180; let left = duration; bodyBox.innerHTML = '<p style="margin:0">Write for three minutes. Use this starter: "What I most want to feel this week is..." — then write without editing.</p>';
      setTimerDisplay(formatTime(left)); timer = setInterval(()=>{ left--; setTimerDisplay(formatTime(left)); if (left<=0){ clearInterval(timer); setTimerDisplay('Time — done'); } },1000);
    }
    function startIntention(){ const duration = 90; let left = duration; bodyBox.innerHTML = '<p style="margin:0">Set a concise intention. Breathe, name the action, then repeat silently. Examples: "I pause before each email" or "I walk 10 minutes daily."</p>';
      setTimerDisplay(formatTime(left)); timer = setInterval(()=>{ left--; setTimerDisplay(formatTime(left)); if (left<=0){ clearInterval(timer); setTimerDisplay('Done'); } },1000);
    }
    function formatTime(s){ const m = Math.floor(s/60); const sec = String(s%60).padStart(2,'0'); return m+':'+sec; }

    // Small utility: year
    document.getElementById('year').textContent = new Date().getFullYear();
  </script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfdfc;--paper:#ffffff;--text:#0e2a23;--muted:#526662;--accent:#2b7a66}
    body{margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,Arial;background:var(--bg);color:var(--text);-webkit-font-smoothing:antialiased}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px;background:white;border-bottom:1px solid rgba(11,34,29,0.04);position:sticky;top:0;z-index:20}
    .logo{display:flex;align-items:center;gap:10px}
    .logo .mark{width:42px;height:42px;background:var(--accent);border-radius:8px;color:white;display:grid;place-items:center;font-weight:700}
    nav a{margin-left:12px;color:var(--muted);text-decoration:none;font-weight:600}
    main{max-width:980px;margin:28px auto;padding:12px}
    .lead{background:linear-gradient(180deg,#fff,rgba(255,255,255,0.8));padding:18px;border-radius:12px;border:1px solid rgba(11,34,29,0.04)}
    h1{margin:0 0 8px 0}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px;margin-top:18px}
    .panel{background:var(--paper);padding:16px;border-radius:10px;border:1px solid rgba(11,34,29,0.04)}
    .muted{color:var(--muted)}
    .story p{margin:0 0 8px 0}
    .values{display:flex;flex-direction:column;gap:8px}
    .value{padding:10px;border-radius:8px;background:#f6fdf9;border:1px solid rgba(74,166,138,0.06)}
    .reveal{opacity:0;transform:translateY(12px);transition:all 520ms cubic-bezier(.2,.9,.3,1)}
    .reveal.is-visible{opacity:1;transform:none}
    @media (max-width:920px){.grid{grid-template-columns:1fr}}
    .pattern{height:120px;background-image:url('assets/img/pattern.svg');background-size:cover;border-radius:10px;opacity:0.08}
  </style>
</head>
<body>
  <header>
    <div class="logo">
      <div class="mark">HM</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav aria-label="Site links">
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="pricing.html">Plans</a>
      <a href="book.html">Schedule</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main>
    <section class="lead reveal" aria-labelledby="about-head">
      <h1 id="about-head">A steady frame for thoughtful change</h1>
      <p class="muted">We combine practical lifestyle tools, relationship-aware planning, and clear education so you can test what fits. Our role is to coach, teach, and support — not to promise cures.</p>
    </section>

    <section class="grid" style="margin-top:16px">
      <div>
        <div class="panel reveal story">
          <h2 style="margin-top:0">Our story</h2>
          <p>We began with a simple question: how do you give people usable practices that actually live inside a busy week? That led us to small, teachable modules and a membership structure for steady practice.</p>
          <p>Our clinicians are trained across nutritional, behavioral, and lifestyle medicine streams and coordinate with primary providers when appropriate. We emphasize education and safety.</p>
        </div>

        <div class="panel reveal" style="margin-top:12px">
          <h3 style="margin-top:0">Approach in brief</h3>
          <ol class="muted">
            <li>Map priorities and constraints</li>
            <li>Choose brief practical experiments</li>
            <li>Practice, review, and adapt</li>
          </ol>
        </div>

        <div class="panel reveal" style="margin-top:12px">
          <h3 style="margin-top:0">People we serve</h3>
          <p class="muted">Busy adults juggling work, caregiving, and recovery who want realistic, evidence-informed steps to steady their routines.</p>
        </div>
      </div>

      <aside>
        <div class="panel reveal">
          <div class="pattern" aria-hidden="true"></div>
          <h3 style="margin-top:8px">Meet the team</h3>
          <p class="muted">A small group of clinicians and coaches with varied training. We coordinate care and emphasize clear next steps.</p>
          <div style="margin-top:12px"><a class="" href="book.html" style="padding:8px 12px;border-radius:8px;background:var(--accent);color:white;text-decoration:none;font-weight:700">Book a time</a></div>
        </div>

        <div class="panel reveal" style="margin-top:12px">
          <h4 style="margin:0">Core values</h4>
          <div class="values" style="margin-top:8px">
            <div class="value">Clarity over jargon</div>
            <div class="value">Small tests, honest review</div>
            <div class="value">Coordination with your care team</div>
          </div>
        </div>
      </aside>
    </section>

    <section style="margin-top:18px" class="reveal panel">
      <h3 style="margin-top:0">Want to try a short practice?</h3>
      <p class="muted">Short practices help ground attention. Use the guided exercise to try breathing, journaling, or setting an intention right away.</p>
      <div style="margin-top:10px"><button class="btn" id="openExercise">Try a short exercise</button></div>
    </section>

    <section style="margin-top:18px" class="reveal panel">
      <h3 style="margin-top:0">Testimonials</h3>
      <p class="muted">"Practical steps that fit my week." — a member in {{CITY}}</p>
    </section>

    <section style="margin-top:18px" class="panel reveal">
      <h3 style="margin-top:0">Contact</h3>
      <p class="muted">Call us at {{PHONE}} or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> to ask about membership types or to coordinate with your clinician.</p>
    </section>
  </main>

  <script>
    // Reveal on scroll with prefers-reduced-motion support
    const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    document.querySelectorAll('.reveal').forEach(el=>{ if (reduceMotion) el.classList.add('is-visible'); });
    if (!reduceMotion && 'IntersectionObserver' in window){
      const obs = new IntersectionObserver((entries)=>{ entries.forEach(e=>{ if (e.isIntersecting) e.target.classList.add('is-visible'); }); },{threshold:0.1});
      document.querySelectorAll('.reveal').forEach(el=>obs.observe(el));
    }

    // Simple modal reused for guided practice
    const modalHtml = `
      <div id="exerciseModal" role="dialog" aria-modal="true" aria-hidden="true" style="position:fixed;inset:0;display:none;align-items:center;justify-content:center;padding:24px;z-index:60">
        <div style="background:rgba(7,51,38,0.9);color:white;padding:18px;border-radius:12px;max-width:720px;width:100%;box-shadow:0 12px 48px rgba(2,10,8,0.5)">
          <div style="display:flex;justify-content:space-between;align-items:center">
            <h2 style="margin:0;font-size:18px">Short guided practice</h2>
            <button id="closeExercise" style="background:transparent;border:0;color:white;font-size:18px;cursor:pointer">✕</button>
          </div>
          <div style="margin-top:12px">Use the "Start" button to try a short practice. This is educational, optional, and you can close at any time.</div>
