    label{display:block;font-weight:700;margin-bottom:6px}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(11,34,29,0.06);margin-bottom:10px}
    .btn{padding:10px 12px;border-radius:8px;border:0;background:var(--accent);color:white;cursor:pointer}
    .note{color:var(--muted);font-size:14px}
    .reveal{opacity:0;transform:translateY(12px);transition:all 520ms cubic-bezier(.2,.9,.3,1)}
    .reveal.is-visible{opacity:1;transform:none}
    @media (max-width:920px){.split{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:10px">
      <div style="width:40px;height:40px;background:var(--accent);border-radius:8px;color:white;display:grid;place-items:center;font-weight:700">HM</div>
      <div style="font-weight:700">{{BUSINESS_NAME}}</div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="pricing.html">Plans</a>
      <a href="about.html">Team</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main>
    <section class="panel reveal">
      <h1 style="margin-top:0">Schedule a planning session</h1>
      <p class="note">Choose a session to map priorities and set a brief practice plan. If you are seeking urgent care, please contact your provider.</p>
    </section>

    <section class="split" style="margin-top:18px">
      <div>
        <div class="panel reveal">
          <h2 style="margin-top:0">Book a session</h2>
          <form id="bookingForm" onsubmit="return false;">
            <label for="name">Full name</label>
            <input id="name" name="name" required>
            <label for="email">Email</label>
            <input id="email" name="email" type="email" required>
            <label for="phone">Phone</label>
            <input id="phone" name="phone" type="tel">
            <label for="type">Session type</label>
            <select id="type" name="type">
              <option value="intro">Planning session — 40 min</option>
              <option value="follow">Follow-up — 25 min</option>
              <option value="extended">Extended planning — 80 min</option>
            </select>
            <label for="note">Brief note</label>
            <textarea id="note" name="note" rows="4" placeholder="What would you like to focus on?"></textarea>
            <div style="margin-top:8px;display:flex;gap:8px;align-items:center">
              <button class="btn" id="submitBooking">Request time</button>
              <button class="btn" id="quickCall" style="background:#fff;border:1px solid rgba(11,34,29,0.06);color:var(--accent)">Call to arrange</button>
            </div>
            <p class="note" style="margin-top:8px">We will confirm availability and next steps by email. Sessions are educational and not emergency medical care.</p>
          </form>
        </div>

        <div class="panel reveal" style="margin-top:12px">
          <h3 style="margin-top:0">Helpful to share</h3>
          <ul class="note">
            <li>Medications or recent tests (summary)</li>
            <li>Primary care contact</li>
            <li>Current sleep, stress, and routines</li>
