          <h3 style="margin-top:0">Quick plan options</h3>
          <div style="display:flex;flex-direction:column;gap:10px;margin-top:8px">
            <div style="padding:10px;border-radius:8px;border:1px solid rgba(11,34,29,0.04)">
              <strong>Intro (40m)</strong>
              <div class="note">Mapping priorities, choosing 1–2 experiments.</div>
            </div>
            <div style="padding:10px;border-radius:8px;border:1px solid rgba(11,34,29,0.04)">
              <strong>Follow-up (25m)</strong>
              <div class="note">Review results and iterate.</div>
            </div>
            <div style="padding:10px;border-radius:8px;border:1px solid rgba(11,34,29,0.04)">
              <strong>Extended (80m)</strong>
              <div class="note">Deep planning for complex changes.</div>
            </div>
          </div>
          <div style="margin-top:12px"><a href="pricing.html" style="text-decoration:none;color:var(--accent);font-weight:700">See membership plans</a></div>
        </div>

        <div class="panel reveal" style="margin-top:12px">
          <h4 style="margin:0">Need something else?</h4>
          <p class="note">Call {{PHONE}} or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> for custom coordination or questions.</p>
        </div>
      </aside>
    </section>

    <section style="margin-top:18px" class="panel reveal">
      <h3 style="margin-top:0">Quick guided practice</h3>
      <p class="note">Before your session, try a short breathing or intention-setting practice to arrive grounded.</p>
      <div style="margin-top:8px"><button class="btn" id="openPractice">Try a short practice</button></div>
    </section>

  </main>

  <script>
    // Reveal with reduced motion respect
    const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    document.querySelectorAll('.reveal').forEach(el=>{ if (reduceMotion) el.classList.add('is-visible'); });
    if (!reduceMotion && 'IntersectionObserver' in window){
      const obs = new IntersectionObserver(entries=>{ entries.forEach(e=>{ if (e.isIntersecting) e.target.classList.add('is-visible'); }); },{threshold:0.12});
      document.querySelectorAll('.reveal').forEach(el=>obs.observe(el));
    }

    // Booking form: local-only simulation
    document.getElementById('submitBooking').addEventListener('click', ()=>{
      const name = document.getElementById('name').value || '—';
      const email = document.getElementById('email').value || '—';
      const type = document.getElementById('type').value;
      alert('Request received for ' + name + ' (' + email + '). We will follow up to confirm availability.');
      document.getElementById('bookingForm').reset();
    });
    document.getElementById('quickCall').addEventListener('click', (e)=>{ e.preventDefault(); alert('Please call ' + '{{PHONE}}' + ' to arrange a time.'); });

    // Small guided practice modal (re-using pattern similar to other pages)
    const modalHtml = `
      <div id="practiceModal" role="dialog" aria-modal="true" aria-hidden="true" style="position:fixed;inset:0;display:none;align-items:center;justify-content:center;padding:24px;z-index:60">
        <div style="background:rgba(7,51,38,0.9);color:white;padding:18px;border-radius:12px;max-width:640px;width:100%">
          <div style="display:flex;justify-content:space-between;align-items:center">
            <h3 style="margin:0">Two-minute grounding</h3>
            <button id="closePractice" style="background:transparent;border:0;color:white;font-size:18px;cursor:pointer">✕</button>
          </div>
          <div style="margin-top:12px">Breathe gently: inhale for 4, exhale for 4. Repeat until the timer ends. Close any time.</div>
          <div style="margin-top:12px"><button id="startShort" class="btn">Start 2-minute practice</button></div>
        </div>
      </div>`;
    document.body.insertAdjacentHTML('beforeend', modalHtml);
    document.getElementById('openPractice').addEventListener('click', ()=>{ document.getElementById('practiceModal').style.display='flex'; document.getElementById('practiceModal').setAttribute('aria-hidden','false'); });
    document.addEventListener('click', (e)=>{ if (e.target && e.target.id==='closePractice') { document.getElementById('practiceModal').style.display='none'; document.getElementById('practiceModal').setAttribute('aria-hidden','true'); } });
    document.getElementById('startShort').addEventListener('click', ()=>{
      let left = 120; const label = document.createElement('div'); label.style.position='fixed'; label.style.bottom='24px'; label.style.left='50%'; label.style.transform='translateX(-50%)'; label.style.background='rgba(7,51,38,0.85)'; label.style.color='white'; label.style.padding='8px 12px'; label.style.borderRadius='8px'; label.style.zIndex=70; document.body.appendChild(label);
      const iv = setInterval(()=>{ left--; label.textContent = 'Time left: ' + Math.ceil(left) + 's'; if (left<=0){ clearInterval(iv); label.textContent = 'Complete'; setTimeout(()=>label.remove(),1000); } },1000);
    });
  </script>
</body>
</html>"} 
